    // Multi-line text with the alignment of the design.
    private static void text(FimGfx g, String s, float x, float y, float w, float h, float size, float lineH, int alignH, int alignV, int argb, String font) {
        String[] lines = s.split("\n", -1);
        float total = lines.length * lineH;
        float ty = alignV == 1 ? y + (h - total) / 2 : alignV == 2 ? y + h - total : y;
        for (String line : lines) {
            float tw = alignH == 0 ? 0 : g.textWidth(line, size, font);
            float tx = alignH == 1 ? x + (w - tw) / 2 : alignH == 2 ? x + w - tw : x;
            g.text(line, tx, ty + (lineH - size) / 2, size, argb, font);
            ty += lineH;
        }
    }
